import icone from './assets/locomotiva.svg';

export default {
  id: 'sequencia',
  nome: 'Complete a sequência',
  descricao: 'Olhe a fila de figuras e descubra qual vem depois.',
  habilidades: ['resposta-social', 'empatia'],
